241	}
242	
243	func TestReorgRemovedSuffixHashesMayReappear(t *testing.T) {
244		index := chain(t,
245			Block{Height: 1, Hash: "h1", Parent: "genesis"},
246			Block{Height: 2, Hash: "h2", Parent: "h1"},
247			Block{Height: 3, Hash: "h3", Parent: "h2"},
248		)
249		// h3 lives in the removed suffix, so it may be reused at a new height.
250		dropped, err := index.Reorg([]Block{
251			{Height: 2, Hash: "h2b", Parent: "h1"},
252			{Height: 3, Hash: "h3", Parent: "h2b"},
253		})
254		if err != nil {
255			t.Fatalf("reorg refused: %v", err)
256		}
257		if !reflect.DeepEqual(dropped, []int64{2, 3}) {
258			t.Fatalf("dropped=%v, want [2 3]", dropped)
259		}
260		if index.ByHash["h3"] != 3 {
261			t.Fatalf("h3 not re-indexed: %v", index.ByHash)
262		}
263	}
264	
265	func TestReorgFailureThenCorrectedRetry(t *testing.T) {
266		index := chain(t,
267			Block{Height: 1, Hash: "h1", Parent: "genesis"},
268			Block{Height: 2, Hash: "h2", Parent: "h1"},
269		)
270		if _, err := index.Reorg([]Block{{Height: 2, Hash: "h2b", Parent: "unknown"}}); err == nil {
