func relocatedHashBranch() []Block {
	return []Block{
		{Height: 3, Hash: "n3", Parent: "h2", Txs: []string{"newA"}},
		{Height: 4, Hash: "h5", Parent: "n3", Txs: []string{"newB"}},
		{Height: 5, Hash: "h4", Parent: "h5", Txs: []string{"newC1", "newC2"}},
